.study-queue-panel {
  background: #1a1a2e;
  border: 2px solid #00ff88;
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
}
.queue-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 20px;
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  border-bottom: 2px solid #00ff88;
}
.queue-title {
  color: #00ff88;
  font-size: 1.3em;
  font-weight: bold;
}
.queue-filters {
  display: flex;
  gap: 10px;
}
.filter-dropdown {
  padding: 8px 12px;
  background: #0a0a0a;
  border: 1px solid #333;
  border-radius: 4px;
  color: #00ff88;
  font-family: inherit;
  font-size: 0.9em;
  cursor: pointer;
}
.filter-dropdown:focus {
  outline: none;
  border-color: #00ff88;
}
.queue-list {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
}
.study-item {
  background: #0a0a0a;
  border: 1px solid #333;
  border-left: 4px solid #00ccff;
  border-radius: 6px;
  padding: 15px;
  margin-bottom: 10px;
  display: grid;
  grid-template-columns: 50px 1fr 120px 100px;
  gap: 15px;
  align-items: center;
  cursor: pointer;
  transition: all 0.2s;
}
.study-item:hover {
  border-left-color: #00ff88;
  background: rgba(0, 255, 136, 0.05);
  transform: translateX(5px);
}
.study-item.priority-high {
  border-left-color: #ff0044;
}
.study-item.priority-medium {
  border-left-color: #ffaa00;
}
.study-icon {
  font-size: 2em;
  text-align: center;
}
.study-info {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.study-patient {
  color: #00ff88;
  font-weight: bold;
  font-size: 1.05em;
}
.study-description {
  color: #888;
  font-size: 0.85em;
}
.study-modality {
  display: inline-block;
  padding: 4px 8px;
  background: rgba(0, 204, 255, 0.2);
  border: 1px solid #00ccff;
  border-radius: 4px;
  color: #00ccff;
  font-size: 0.75em;
  font-weight: bold;
}
.study-status {
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 0.8em;
  font-weight: bold;
  text-align: center;
}
.study-status.pending {
  background: rgba(255, 170, 0, 0.2);
  border: 1px solid #ffaa00;
  color: #ffaa00;
}
.study-status.processing {
  background: rgba(0, 204, 255, 0.2);
  border: 1px solid #00ccff;
  color: #00ccff;
}
.study-status.completed {
  background: rgba(0, 255, 136, 0.2);
  border: 1px solid #00ff88;
  color: #00ff88;
}

