function initStudyQueuePanel(element, config) {
  const listContainer = element.querySelector('#' + config.id + '-list');
  const modalityFilter = element.querySelector('#' + config.id + '-modality');
  const statusFilter = element.querySelector('#' + config.id + '-status');

  let studies = [];

  function updateQueue(studyData) {
    studies = studyData;
    renderQueue();
  }

  function renderQueue() {
    const modality = modalityFilter.value;
    const status = statusFilter.value;

    let filtered = studies;
    if (modality !== 'all') {
      filtered = filtered.filter(s => s.modality === modality);
    }
    if (status !== 'all') {
      filtered = filtered.filter(s => s.status === status);
    }

    listContainer.innerHTML = '';
    filtered.forEach(study => {
      const item = createStudyItem(study);
      listContainer.appendChild(item);
    });
  }

  function createStudyItem(study) {
    const div = document.createElement('div');
    div.className = 'study-item';
    if (study.priority) {
      div.classList.add('priority-' + study.priority);
    }

    const icon = study.priority === 'high' ? '🔴' : study.priority === 'medium' ? '🟡' : '🟢';

    div.innerHTML = `
      <div class="study-icon">${icon}</div>
      <div class="study-info">
        <div class="study-patient">${study.patientName}</div>
        <div class="study-description">${study.description}</div>
        <div><span class="study-modality">${study.modality}</span></div>
      </div>
      <div style="font-size: 0.85em; color: #888;">
        <div>${study.time}</div>
        <div>Series: ${study.seriesCount || 0}</div>
      </div>
      <div class="study-status ${study.status}">${study.status.toUpperCase()}</div>
    `;

    div.addEventListener('click', () => {
      if (config.onStudyClick) {
        config.onStudyClick(study);
      }
    });

    return div;
  }

  modalityFilter.addEventListener('change', renderQueue);
  statusFilter.addEventListener('change', renderQueue);

  return { updateQueue };
}
